import type JSZip from "jszip";

/**
 * 批量导入的纯解析层：把「粘贴的一列词」或 CSV/TSV/XLSX 文件变成干净的
 * 词条数组。这里不碰 React、不碰 store，方便单测。
 *
 * 只取每行的第一列 —— 词表的第一列就是单词本身，后面几列（音标、释义、
 * 出处……）在导入后会由词典重新补全，不采信粘贴文本里的手工标注。
 */

export interface ParsedWordList {
  /** 去重后的词条，保留首次出现的写法。 */
  words: string[];
  /** 同一批里重复出现的次数（保留第一次）。 */
  duplicates: number;
}

const HEADER_WORDS = new Set([
  "word",
  "words",
  "term",
  "terms",
  "english",
  "vocabulary",
  "单词",
  "词汇",
  "英文",
]);

function cleanCell(value: string): string {
  let text = value.replace(/^﻿/, "").trim();
  const first = text[0];
  const last = text[text.length - 1];
  if (
    text.length >= 2 &&
    ((first === '"' && last === '"') || (first === "'" && last === "'"))
  ) {
    // 成对引号是 CSV 的常规转义，剥掉；落单的引号按普通字符处理。
    text = text.slice(1, -1).trim();
  }
  return text.replace(/\s+/g, " ");
}

/** 取一行里的第一个单元格：引号包裹的整段、或到第一个制表符/逗号为止。 */
function firstCell(line: string): string {
  const text = line.trim();
  if (!text) return "";
  const quote = text[0];
  if (quote === '"' || quote === "'") {
    const end = text.indexOf(quote, 1);
    return cleanCell(end > 0 ? text.slice(1, end) : text.slice(1));
  }
  const tab = text.indexOf("\t");
  const comma = text.indexOf(",");
  const cut = tab >= 0 && (comma < 0 || tab < comma) ? tab : comma;
  return cleanCell(cut >= 0 ? text.slice(0, cut) : text);
}

/**
 * 解析粘贴文本 / CSV / TSV：每行一个词，只取首列；空行忽略；首行若是
 * 「word / 单词」这类表头则跳过；大小写不同的重复（Apple / apple）视为
 * 同一个词，保留先出现的那次写法。
 */
export function parseWordListText(text: string): ParsedWordList {
  const seen = new Set<string>();
  const words: string[] = [];
  let duplicates = 0;
  let firstDataRow = true;
  for (const rawLine of text.split(/\r?\n/)) {
    if (!rawLine.trim()) continue;
    const cell = firstCell(rawLine);
    if (!cell) continue;
    if (firstDataRow) {
      firstDataRow = false;
      if (HEADER_WORDS.has(cell.toLowerCase())) continue;
    }
    const key = cell.toLowerCase();
    if (seen.has(key)) {
      duplicates += 1;
      continue;
    }
    seen.add(key);
    words.push(cell);
  }
  return { words, duplicates };
}

/**
 * dev 环境里 jszip 在 vite 的 optimizeDeps.exclude 名单里，会被原样直出：
 * 动态导入只能拿到空命名空间，UMD 兜底把类挂在了 globalThis.JSZip 上；
 * 生产构建则走 Rollup 的 CJS interop，default 就是类本身。两条路都接上。
 */
async function loadJSZip(): Promise<typeof JSZip> {
  const module = (await import("jszip")) as { default?: typeof JSZip };
  const constructor =
    module.default ?? (globalThis as { JSZip?: typeof JSZip }).JSZip;
  if (!constructor) throw new Error("JSZip 未能加载");
  return constructor;
}

function decodeXml(value: string): string {
  return value
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex: string) =>
      String.fromCodePoint(parseInt(hex, 16)),
    )
    .replace(/&#(\d+);/g, (_, code: string) =>
      String.fromCodePoint(Number(code)),
    )
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&");
}

function stripTags(value: string): string {
  return decodeXml(value.replace(/<[^>]*>/g, ""));
}

function textRuns(body: string): string {
  return [...body.matchAll(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g)]
    .map((match) => decodeXml(match[1] ?? ""))
    .join("");
}

async function readSharedStrings(zip: JSZip): Promise<string[]> {
  const file = zip.file("xl/sharedStrings.xml");
  if (!file) return [];
  const xml = await file.async("string");
  const strings: string[] = [];
  for (const match of xml.matchAll(/<si(?:\s[^>]*)?>([\s\S]*?)<\/si>/g)) {
    strings.push(textRuns(match[1] ?? ""));
  }
  return strings;
}

/** 取第一个工作表 A 列的全部单元格值（共享字符串 / 内联 / 数值）。 */
function extractColumnA(xml: string, sharedStrings: string[]): string[] {
  const values: string[] = [];
  for (const match of xml.matchAll(/<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)) {
    const attrs = match[1] ?? "";
    const body = match[2] ?? "";
    const reference = /\br="([A-Z]+)\d+"/.exec(attrs)?.[1];
    if (reference !== "A") continue;
    const type = /\bt="([^"]+)"/.exec(attrs)?.[1];
    if (type === "s") {
      const index = Number(stripTags(body).trim());
      values.push(sharedStrings[index] ?? "");
    } else if (type === "inlineStr") {
      values.push(textRuns(body));
    } else {
      values.push(stripTags(body));
    }
  }
  return values;
}

/**
 * 解析 XLSX 的第一个工作表：只需要 A 列，所以不引入完整的表格引擎 ——
 * 解出 xl/sharedStrings.xml 与 xl/worksheets/sheet1.xml 两个成员即可。
 */
export async function parseXlsxWordList(
  buffer: ArrayBuffer,
): Promise<ParsedWordList> {
  const zipCtor = await loadJSZip();
  const zip = await zipCtor.loadAsync(buffer);
  const sharedStrings = await readSharedStrings(zip);
  const sheet =
    zip.file("xl/worksheets/sheet1.xml") ??
    zip.file(/^xl\/worksheets\/.*\.xml$/)[0];
  if (!sheet) return { words: [], duplicates: 0 };
  const xml = await sheet.async("string");
  return parseWordListText(extractColumnA(xml, sharedStrings).join("\n"));
}
